fn promote(self: *BaseParser, token: Token) u16 {
    // The ordinal of a match made in an earlier state (before a
    // reduction) is not this match's.
    self.lastMatchedId = 0;
    const text = self.tokenText(token);
    if (text.len == 0) return promotableSymbol;
    if (self.tryPromote(0, text, ctxAs, &ctxToSymbol, ctxFallbackSymbol, true)) |sym| return sym;
    return promotableSymbol;
}

fn executeAction(self: *BaseParser, ruleId: u16, pass: []Sexp) Sexp {
    return switch (ruleId) {
        0 => self.buildOf(&.{ .{ .tag = .@"module" } }, pass, .tree, false),
        1 => blk: { const out = self.allocItems(1 + pass[0].items().len) catch break :blk self.oomNil(); var n: usize = 0; out[n] = .{ .tag = .@"module" }; n += 1; @memcpy(out[n..][0..pass[0].items().len], pass[0].items()); n += pass[0].items().len; break :blk self.finishItems(out, .tree); },
        2 => self.buildOf(&.{ .{ .elem = 0 } }, pass, .spread, false),
        3 => blk: { const out = self.extendBy(pass, 0, 1) catch break :blk self.oomNil(); var n = out.len; out.items[n] = pass[2]; n += 1; break :blk self.keepExtended(out, n, pass, 0, .spread, false); },
        5 => self.buildOf(&.{ .{ .tag = .@"block" } }, pass, .tree, false),
        6 => blk: { const out = self.allocItems(1 + pass[1].items().len) catch break :blk self.oomNil(); var n: usize = 0; out[n] = .{ .tag = .@"block" }; n += 1; @memcpy(out[n..][0..pass[1].items().len], pass[1].items()); n += pass[1].items().len; break :blk self.finishItems(out, .tree); },
        13 => self.buildOf(&.{ .{ .tag = .@"labeled" }, .{ .elem = 1 }, .{ .elem = 3 } }, pass, .tree, false),
        14 => self.buildOf(&.{ .{ .tag = .@"labeled" }, .{ .elem = 1 }, .{ .elem = 3 } }, pass, .tree, false),
        16 => self.build(&.{ .{ .tag = .@"if" }, pass[2], self.nested(self.buildOf(&.{ .{ .tag = .@"block" }, .{ .elem = 0 } }, pass, .tree, false), 0, 0), .nil }, .tree),
        19 => self.buildOf(&.{ .{ .tag = .@"set" }, .{ .tag = .@"fixed" }, .{ .elem = 0 }, .nil, .{ .elem = 2 } }, pass, .tree, false),
        20 => self.buildOf(&.{ .{ .tag = .@"set" }, .nil, .{ .elem = 0 }, .{ .elem = 2 }, .{ .elem = 4 } }, pass, .tree, false),
        21 => self.buildOf(&.{ .{ .tag = .@"set" }, .{ .tag = .@"fixed" }, .{ .elem = 0 }, .{ .elem = 2 }, .{ .elem = 4 } }, pass, .tree, false),
        22 => self.buildOf(&.{ .{ .tag = .@"set" }, .{ .tag = .@"shadow" }, .{ .elem = 1 }, .nil, .{ .elem = 3 } }, pass, .tree, false),
