        32 => self.build(&.{ .{ .tag = .@"destructure" }, .nil, pass[0], self.nested(blk1: { const out = self.allocItems(1 + pass[2].items().len) catch break :blk1 self.oomNil(); var n: usize = 0; out[n] = .{ .tag = .@"results" }; n += 1; @memcpy(out[n..][0..pass[2].items().len], pass[2].items()); n += pass[2].items().len; break :blk1 self.finishItems(out, .tree); }, 2, 2) }, .tree),
