/// First slot of rest role `role` in nodes of `kind`.
fn restSlotOf(kind: Tag, role: Role) ?usize {
    return switch (kind) {
        .@"module" => if (role == .@"decls") 1 else null,
        .@"struct" => if (role == .@"members") 4 else null,
        .@"enum" => if (role == .@"members") 3 else null,
        .@"errors" => if (role == .@"members") 2 else null,
        .@"error_join" => if (role == .@"members") 3 else null,
        .@"generic_struct" => if (role == .@"members") 5 else null,
        .@"generic_enum" => if (role == .@"members") 4 else null,
        .@"api" => if (role == .@"members") 3 else null,
        .@"api_add" => if (role == .@"members") 3 else null,
        .@"zig_extern" => if (role == .@"decls") 2 else null,
        .@"results" => if (role == .@"values") 1 else null,
        .@"match" => if (role == .@"arms") 2 else null,
        .@"alt_pattern" => if (role == .@"alts") 1 else null,
        .@"variant_pattern" => if (role == .@"bindings") 2 else null,
        .@"panic" => if (role == .@"args") 1 else null,
        .@"block" => if (role == .@"stmts") 1 else null,
        .@"captures" => if (role == .@"caps") 1 else null,
        .@"call" => if (role == .@"args") 3 else null,
        .@"builtin" => if (role == .@"args") 2 else null,
        .@"inst" => if (role == .@"args") 2 else null,
        .@"ct_call" => if (role == .@"args") 2 else null,
        .@"array" => if (role == .@"elems") 1 else null,
        .@"tuple" => if (role == .@"elems") 1 else null,
        .@"generic_inst" => if (role == .@"args") 2 else null,
        .@"results_type" => if (role == .@"types") 1 else null,
        else => null,
    };
}

